// providers.oracle — replays every frozen case in provider_oracle.json
// against the C++ provider SDK. The fixture is generated by
// tools/oracle/generate_provider_fixtures.py from the real Python
// implementation; problem lists must match verbatim (order included).
// Convention: workflow.contracts / prediction.contracts runners.

#include <cstdio>
#include <fstream>
#include <stdexcept>
#include <string>
#include <vector>

#include <pwb/domain/json.hpp>
#include <pwb/providers/contracts.hpp>
#include <pwb/providers/schema.hpp>

using pwb::domain::Json;
namespace pp = pwb::providers;

int g_failures = 0;
int g_checks = 0;

void check(bool ok, const std::string& what) {
    ++g_checks;
    if (!ok) {
        std::fprintf(stderr, "FAIL %s\n", what.c_str());
        ++g_failures;
    }
}

bool problems_equal(const Json& frozen, const std::vector<std::string>& actual) {
    if (!frozen.is_array() || frozen.size() != actual.size()) return false;
    for (std::size_t i = 0; i < actual.size(); ++i) {
        if (!frozen[i].is_string() || frozen[i].get<std::string>() != actual[i]) {
            return false;
        }
    }
    return true;
}

std::string dump_problems(const std::vector<std::string>& problems) {
    std::string out = "[";
    for (std::size_t i = 0; i < problems.size(); ++i) {
        if (i != 0) out += ", ";
        out += "'" + problems[i] + "'";
    }
    return out + "]";
}

pp::ProviderDescriptor descriptor_from_dict(const Json& d) {
    pp::ProviderDescriptor out;
    out.provider_id = d.at("provider_id").get<std::string>();
    auto family = pp::family_from_string(d.at("family").get<std::string>());
    if (!family.has_value()) {
        throw std::invalid_argument("fixture family unknown to C++: " +
                                    d.at("family").get<std::string>());
    }
    out.family = *family;
    out.version = d.at("version").get<std::string>();
    out.display_name = d.at("display_name").get<std::string>();
    out.description = d.at("description").get<std::string>();
    for (const auto& c : d.at("capabilities")) out.capabilities.push_back(c.get<std::string>());
    for (const auto& t : d.at("input_types")) out.input_types.push_back(t.get<std::string>());
    for (const auto& t : d.at("output_types")) out.output_types.push_back(t.get<std::string>());
    out.parameters_schema = d.at("parameters_schema");
    const Json& profile = d.at("resource_profile");
    out.resource_profile.estimated_cpu_cores =
        profile.at("estimated_cpu_cores").get<double>();
    out.resource_profile.estimated_ram_bytes =
        profile.at("estimated_ram_bytes").get<long long>();
    out.resource_profile.estimated_vram_bytes =
        profile.at("estimated_vram_bytes").get<long long>();
    out.resource_profile.io_weight = profile.at("io_weight").get<double>();
    out.resource_profile.category = profile.at("category").get<std::string>();
    out.supports_cancel = d.at("supports_cancel").get<bool>();
    out.supports_resume = d.at("supports_resume").get<bool>();
    out.deterministic = d.at("deterministic").get<bool>();
    out.threading_model = d.at("threading_model").get<std::string>();
    if (d.at("build_identity").is_string()) {
        out.build_identity = d.at("build_identity").get<std::string>();
    }
    return out;
}

int main(int argc, char** argv) {
    const char* fixture_path = PWB_PROVIDERS_FIXTURE;
    if (argc > 1) fixture_path = argv[1];
    std::ifstream in(fixture_path);
    if (!in) {
        std::fprintf(stderr, "FAIL cannot open fixture %s\n", fixture_path);
        return 1;
    }
    Json fixture;
    try {
        in >> fixture;
    } catch (const std::exception& exc) {
        std::fprintf(stderr, "FAIL fixture parse: %s\n", exc.what());
        return 1;
    }
    check(fixture.contains("cases") && fixture["cases"].is_array(),
          "fixture has cases array");
    const Json& cases = fixture.at("cases");
    check(cases.size() >= 50, "fixture case volume");

    // The typed-ref vocabulary agrees with the frozen Python vocabulary.
    std::vector<std::string> frozen_refs;
    for (const auto& r : fixture.at("typed_refs")) frozen_refs.push_back(r.get<std::string>());
    check(frozen_refs == pp::typed_refs(), "typed_refs vocabulary parity");

    int param_cases = 0;
    int descriptor_cases = 0;
    for (const auto& case_item : cases) {
        const std::string id = case_item.at("id").get<std::string>();
        const std::string fn = case_item.at("fn").get<std::string>();
        const Json& frozen = case_item.at("problems");
        try {
            if (fn == "validate_parameters") {
                ++param_cases;
                auto actual = pp::validate_parameters(case_item.at("schema"),
                                                      case_item.at("parameters"),
                                                      case_item.at("label").get<std::string>());
                check(problems_equal(frozen, actual),
                      id + ": problems " + dump_problems(actual) + " != frozen " +
                          frozen.dump());
            } else if (fn == "validate_descriptor") {
                ++descriptor_cases;
                const pp::ProviderDescriptor descriptor =
                    descriptor_from_dict(case_item.at("descriptor"));
                auto actual = pp::validate_descriptor(descriptor);
                check(problems_equal(frozen, actual),
                      id + ": problems " + dump_problems(actual) + " != frozen " +
                          frozen.dump());
            } else {
                check(false, id + ": unknown fn " + fn);
            }
        } catch (const std::exception& exc) {
            check(false, id + ": threw " + exc.what());
        }
    }
    check(param_cases >= 30, "validate_parameters coverage");
    check(descriptor_cases >= 20, "validate_descriptor coverage");

    // Comparator sanity (negative self-check): the comparator must reject a
    // perturbed verdict, not just accept everything.
    const Json& first = cases.at(0);
    std::vector<std::string> wrong = {"deliberately wrong"};
    check(!problems_equal(first.at("problems"), wrong),
          "comparator rejects perturbed verdict");

    if (g_failures != 0) {
        std::fprintf(stderr, "providers.oracle: %d checks, %d failures\n", g_checks,
                     g_failures);
        return 1;
    }
    std::printf("providers.oracle: %d checks passed (%d frozen cases)\n", g_checks,
                static_cast<int>(cases.size()));
    return 0;
}
